import {attachCardDrag} from '../shared/drag.js';
import {mountExperiment} from '../model-kit/session.js';
import {definition} from '../../../embed/definitions/lab-context.js';
import {e} from '../../../embed/definitions/_lab.js';
import {factIds,labels,layerNames,scenarios,project,compare,summary,describe,loadScenario,prioritize,decisionFirst,valueText} from './model.js';
const numeric=(key,value,label,min,max,index='')=>`<label for="context-${key}-${index}">${e(label)}<input id="context-${key}-${index}" type="number" min="${min}" max="${max}" step="1" value="${value}" data-field="${key}" ${index!==''?`data-index="${index}"`:''}></label>`;
function render(state,{pinned}){
 const r=project(state),c=compare(state,pinned);
 return `<div class="experiment-toolbar"><label for="context-scenario">Situation<select id="context-scenario">${Object.entries(scenarios).map(([id,s])=>`<option value="${id}" ${state.scenario===id?'selected':''}>${e(s.label)}</option>`).join('')}</select></label><button id="context-decision-first">Put decision conditions first</button></div><p class="context-intro">${e(scenarios[state.scenario].description)} Give each layer a priority order. Only whole facts that fit its attention budget travel onward.</p>
 <section class="context-verdict experiment-output" aria-label="Decision results"><div><span>From the available facts</span><strong data-context-choice>${r.decision.choice}</strong><p>${e(r.decision.reasons.join(' '))}</p></div><div><span>The same rule, all facts</span><strong>${r.full.choice}</strong><p>${r.differs?'An omission changes the decision.':'This decision survives the reporting chain.'} ${r.report.length}/8 facts survive; ${r.retrieved.length} retrieved; ${r.reading} attention units read.</p></div></section>
 ${c?`<div class="context-comparison"><h3>Pinned reporting arrangement · current facts</h3><p>${e(summary(state,c.result))}</p><p>Replays pinned priorities, capacities, source requests and unknown-evidence policy on current facts, costs, rule threshold and retrieval window.${c.situationChanged?' These situation assumptions have changed since pinning.':''}</p></div>`:''}
 <p class="context-pan">Swipe across the three reports →</p><section class="context-chain experiment-board" aria-label="Three reporting layers">${r.layers.map(l=>`<section class="context-layer" aria-label="${e(layerNames[l.index])}"><header><p class="context-step">0${l.index+1} / REPORT</p><h2>${e(layerNames[l.index])}</h2>${numeric('capacities',state.capacities[l.index],'Attention budget',1,24,l.index)}<p>${l.used} used · ${l.remaining} spare · ${l.carried.length} facts carried</p></header><ol class="context-facts">${state.orders[l.index].map((id,pos)=>{const status=l.carried.includes(id)?'carried':l.received.includes(id)?'dropped':'absent';return `<li class="context-fact ${status}" data-drag-id="${l.index}:${id}" data-drop-id="${l.index}:${id}" data-fact="${id}" data-layer="${l.index}"><div><strong data-drag-handle title="Drag to move; the priority menu provides the keyboard alternative">${e(labels[id])}</strong><span>${status==='absent'?'Already omitted upstream':`${valueText(id,state.facts[id])} · ${state.costs[id]} unit${state.costs[id]===1?'':'s'}`}</span><small>${status==='carried'?'Carried forward':status==='dropped'?'Does not fit':'Unavailable'}</small></div><label class="context-priority" for="context-order-${l.index}-${id}"><span class="sr-only">Priority of ${e(labels[id])} in ${e(layerNames[l.index])}</span><select id="context-order-${l.index}-${id}" data-priority="${id}" data-layer="${l.index}" aria-label="Priority of ${e(labels[id])} in ${e(layerNames[l.index])}">${factIds.map((_,i)=>`<option value="${i}" ${pos===i?'selected':''}>${i+1}</option>`).join('')}</select></label></li>`;}).join('')}</ol><p class="context-dropped">Omitted here: ${e(l.dropped.map(id=>labels[id]).join(', ')||'none')}.</p></section>`).join('')}</section>
 <p class="context-hint">Drag within a column or choose a priority number. A later layer cannot restore a fact omitted upstream.</p>
 <section class="context-retrieval"><div><p class="context-step">04 / GO BACK TO THE SOURCE</p><h2>Which question is worth asking?</h2><p>Requests run in the order selected. A reply arrives only if it fits the remaining window; facts already in the brief need no request.</p><div class="context-assumptions">${numeric('decisionWindow',state.decisionWindow,'Time before decision (ticks)',0,12)}${numeric('queryDuration',state.queryDuration,'Ticks per source request',1,4)}</div></div><div class="context-queries">${factIds.map(id=>`<label class="context-query"><input type="checkbox" id="context-query-${id}" data-query="${id}" ${state.queries.includes(id)?'checked':''}><span><strong>${e(labels[id])}</strong><small>${r.report.includes(id)?'Already in brief':r.retrieved.includes(id)?`Retrieved: ${valueText(id,state.facts[id])}`:r.unanswered.includes(id)?'No time for reply':'Not in brief'}${state.queries.includes(id)?` · request ${state.queries.indexOf(id)+1}`:''}</small></span></label>`).join('')}<p>${r.queryTime} of ${state.decisionWindow} ticks used.${r.unanswered.length?` Unanswered: ${e(r.unanswered.map(id=>labels[id]).join(', '))}.`:''}</p></div></section>
 <details id="context-source"><summary>Edit the original facts and their attention costs</summary><p>Values are fictional assumptions. A cost is the attention needed to carry the whole fact, not its importance.</p><div class="context-source-facts">${factIds.map(id=>`<div><strong>${e(labels[id])}</strong>${typeof state.facts[id]==='boolean'?`<label for="context-facts-${id}">Source value<select id="context-facts-${id}" data-field="facts" data-index="${id}" data-boolean><option value="true" ${state.facts[id]?'selected':''}>Yes</option><option value="false" ${!state.facts[id]?'selected':''}>No</option></select></label>`:numeric('facts',state.facts[id],'Source value',0,id==='reach'?1000:id==='date'?30:id==='sentiment'?10:100,id)}${numeric('costs',state.costs[id],'Attention units',1,4,id)}</div>`).join('')}</div></details>
 <details id="context-rule"><summary>Inspect and change the decision rule</summary><div class="context-assumptions">${numeric('threshold',state.threshold,'Readiness required (%)',0,100)}<label for="context-unknown">When required evidence is missing<select id="context-unknown" data-field="unknown">${['launch','pilot','hold'].map(v=>`<option value="${v}" ${v===state.unknown?'selected':''}>${v}</option>`).join('')}</select></label></div><ol class="context-rule"><li>Hold if a known blocker exists, the partner is known to be unready, or known readiness is below the threshold.</li><li>Otherwise pilot if rollback is known to be unavailable.</li><li>Otherwise apply the chosen missing-evidence policy if any of those four facts is absent.</li><li>Otherwise launch. Reach, budget, announcement date and interviews do not enter this rule.</li></ol><p>The full-information decision applies exactly the same rule to every original fact. It is a comparison, not an objectively correct recommendation.</p></details>
 <details id="context-mechanism"><summary>How this model works · limits and source</summary><p>Each report starts from the facts it receives. It checks them in your order, carries a fact when the whole attention cost fits, and skips it otherwise. Spare attention can go to a smaller lower-priority fact. An omitted fact stays absent downstream until an explicit source request returns it.</p><p>Source retrieval is accurate and serial. Reporting itself has no elapsed-time cost here; only source requests consume the stated decision window. Selection models neither language understanding nor summarisation: facts are never rewritten. There is no motive, trust, persuasion, ambiguity or deception model. Attention costs and the decision rule are challengeable assumptions.</p><p>Inspired by John Cutler’s <a href="https://cutlefish.substack.com/p/tbm-437-ai-and-the-recontextualization" target="_blank" rel="noopener">AI and the Recontextualization Tax</a>. This explicit fact-selection mechanism is an original experiment, not a simulation of Cutler’s complete argument.</p></details>`;
}
function bind({root,state,change}){
 root.querySelector('#context-scenario').addEventListener('change',event=>change(loadScenario(state,event.target.value),'Source situation changed; reporting arrangement retained.'));
 root.querySelector('#context-decision-first').addEventListener('click',()=>change(decisionFirst(state),'Decision conditions moved to the front of each report.'));
 root.querySelectorAll('[data-priority]').forEach(input=>input.addEventListener('change',()=>change(prioritize(state,Number(input.dataset.layer),input.dataset.priority,Number(input.value)),'Reporting priority changed.')));
 root.querySelectorAll('[data-field]').forEach(input=>input.addEventListener('change',()=>{const next=structuredClone(state),{field,index}=input.dataset,value=input.hasAttribute('data-boolean')?input.value==='true':field==='unknown'?input.value:Number(input.value);if(index!==undefined&&index!=='')next[field][field==='capacities'?Number(index):index]=value;else next[field]=value;change(next,'Fact or assumption changed.');}));
 root.querySelectorAll('[data-query]').forEach(input=>input.addEventListener('change',()=>{const next=structuredClone(state),id=input.dataset.query;next.queries=input.checked?[...next.queries,id]:next.queries.filter(v=>v!==id);change(next,'Source requests changed.');}));
 // A designated pointer handle leaves the priority select usable and supports touch.
 return attachCardDrag({root,onDrop:({itemId,dropId})=>{const [layer,id]=itemId.split(':'),[targetLayer,targetId]=dropId.split(':');if(layer!==targetLayer)return;change(prioritize(state,Number(layer),id,state.orders[Number(layer)].indexOf(targetId)),'Fact priority moved.');}});
}
await mountExperiment({route:'context',definition,render,bind,describe});
